<template>
  <ConsumerShell>
    <div class="premium-rooms">
    <ConsumerPageHeader :title="roomId ? '参赛房间' : '找队友'" :description="roomId ? undefined : '选择双打项目，创建房间、申请加入或自动匹配。'">
      <router-link class="btn" :to="roomId ? '/portal/rooms' : '/public/events'">{{ roomId ? '返回房间列表' : '选择赛事' }}</router-link>
    </ConsumerPageHeader>
    <nav class="personal-nav"><router-link to="/portal/registration">我的报名</router-link><router-link class="active" to="/portal/rooms">找队友</router-link><router-link to="/portal/teams">我的队伍</router-link><router-link to="/portal/growth">成长与荣誉</router-link></nav>
    <ConsumerState v-if="loading" loading title="正在加载房间" />
    <ConsumerState v-else-if="error" error title="还有一步需要处理" :description="error"><button class="btn" @click="load()">重新读取</button><router-link class="btn" :to="{path:'/portal/identity',query:{returnTo:$route.fullPath}}">补齐参赛资料</router-link></ConsumerState>
    <section v-if="!loading && !error && visibleOffers.length" class="match-offers consumer-card" aria-live="polite"><h3>组队邀请</h3><article v-for="offer in visibleOffers" :key="offer.id"><div><strong>{{ offer.event_name }} · {{ offer.unit_name }}</strong><p>{{ offer.my_status==='accepted' ? '你已接受，等待搭档确认' : '双方确认后才进入房间' }}<span class="offer-timer">{{ remaining(offer.expires_at) }} 秒</span></p></div><SportButton v-if="offer.my_status==='pending'" :disabled="busy || !!pollError || remaining(offer.expires_at)===0" @click="answer(offer.id,'accept')">接受邀请</SportButton><SportButton variant="secondary" :disabled="busy || !!pollError" @click="answer(offer.id,'decline')">婉拒</SportButton></article></section>
    <p v-if="pollError && !error" class="room-refresh-warning" role="status">{{ pollError }}<button :disabled="busy" @click="load(true)">重新同步</button></p>
    <template v-if="!loading && !error && detail && roomId">
      <section class="room-stage">
        <div class="room-context"><div><h2>{{detail.room.name}}</h2><router-link :to="'/public/events/'+detail.room.event_id">{{detail.room.event_name}}</router-link><span> / {{detail.room.unit_name}}</span></div><span class="room-badge">{{detail.room.registration_id?'已生成报名':detail.members.length<detail.room.max_members?'待补员':allReady?'可以报名':'待确认准备'}}</span></div>
        <div class="room-topline"><span>{{ detail.room.type_name }} · {{ detail.members.length }}/{{ detail.room.max_members }} 人</span><span>{{detail.members.filter(m=>m.ready).length}} 人已准备</span></div>
        <p v-if="detail.room.team_id" class="team-banner">{{detail.room.team_name}}<el-tag v-if="detail.room.team_title" type="warning" size="small">{{detail.room.team_title}}</el-tag></p><div class="room-seats">
          <SportsProfileCard v-for="member in detail.members" :key="member.account_id" :honors="certifiedByAccount[member.account_id]" :sport-id="detail.room.sport_id" class="room-person-card" compact><SportsAvatar :nickname="member.nickname" :account-id="member.account_id" :avatar-file-id="member.avatar_file_id" :tone="member.avatar_style" :title="member.title" :title-code="member.title_code" :points="member.points" :rank-level="member.rank_index" :rank-name="member.rank_name" :ready="member.ready" :captain="member.account_id === detail.room.host_account_id" :captain-label="detail.room.team_id?'队长':'房主'" /></SportsProfileCard>
          <div v-for="seat in Math.max(0, detail.room.max_members-detail.members.length)" :key="'seat'+seat" class="empty-seat"><button v-if="isHost && !detail.room.registration_id" type="button" :disabled="busy" aria-label="发布招募邀请搭档" @click="recruitVisible=true">＋</button><span v-else>＋</span><strong>空缺席位</strong><small>{{ isHost ? '发布招募' : '等待房主邀请队友' }}</small></div>
        </div>
        <p v-if="honorError" class="room-note">认证荣誉暂未同步。<button class="retry-honor" :disabled="busy" @click="loadCertifiedBadges(true)">重新读取荣誉</button></p>
        <p v-if="detail.room.announcement" class="room-announcement">📌 {{ detail.room.announcement }}</p>
        <div class="room-actions" v-if="!detail.room.registration_id">
          <SportButton :variant="myMember?.ready ? 'secondary' : 'primary'" :busy="busy" :disabled="!!pollError" @click="ready">{{ myMember?.ready ? '取消准备' : '确认准备' }}</SportButton>
          <SportButton variant="secondary" v-if="isHost && detail.members.length < detail.room.max_members" :busy="busy" :disabled="!!pollError" @click="recruitVisible=true">发布招募</SportButton>
          <SportButton variant="secondary" v-if="isHost && detail.members.length < detail.room.max_members" :busy="busy" :disabled="!!pollError" @click="match(detail.room.unit_id, roomId)">自动匹配</SportButton>
          <SportButton v-if="isHost" variant="primary" :busy="busy" :disabled="!allReady || !!pollError" @click="prepare">生成报名</SportButton>
        </div>
        <router-link v-else class="btn primary" :to="'/portal/registration/detail/'+detail.room.registration_id">查看报名</router-link>
        <p class="room-note">{{detail.room.registration_id?'报名已生成，请各自确认参赛资料和声明。':detail.members.length<detail.room.max_members?'还缺 '+(detail.room.max_members-detail.members.length)+' 人，房主可发布招募或自动匹配。':!allReady?'等待未准备的成员确认后，房主可生成报名。':'成员已集齐并准备，房主可生成本场报名。'}}</p>
        <router-link class="room-profile-link" :to="{path:'/portal/profile',query:{returnTo:route.fullPath}}">完善我的资料<ConsumerIcon name="chevron"/></router-link>
        <div v-if="visibleRequests.length" class="room-matching-status" role="status"><span class="matching-orbit"/><div><strong>{{ visibleRequests[0].status==='offered'?'搭档邀请已送达':'正在寻找本场搭档' }}</strong><p>匹配席位先邀请确认，正式报名仍需本人确认资料。</p></div><SportButton variant="ghost" :busy="busy" @click="stopMatch(visibleRequests[0].id)">取消匹配</SportButton></div>
      </section>
      <div class="room-bottom-grid">
        <section class="consumer-card"><h3>房间动态</h3><div class="encouragements"><button v-for="message in cheers" :key="message" :disabled="busy || !!pollError" @click="encourage(message)">{{ message }}</button></div><div class="room-feed" aria-live="polite"><p v-for="(item,index) in detail.interactions.slice(0,5)" :key="index"><strong>{{ item.nickname }}</strong><span>{{ item.text }}</span></p><small v-if="!detail.interactions.length">暂无动态</small></div></section>
        <section class="consumer-card"><h3>本场准备清单</h3><ol class="room-checklist"><li :class="{done:detail.members.length===detail.room.max_members}">集齐本场搭档</li><li :class="{done:allReady}">每人确认准备</li><li :class="{done:!!detail.room.registration_id}">进入报名，核对个人资料和声明</li><li>房主正式提交后，再核对付款安排</li></ol><details v-if="!detail.room.registration_id"><summary>房间管理</summary><SportButton v-if="isHost" variant="ghost" @click="editAnnouncement">编辑公告</SportButton><SportButton variant="danger" @click="leave">退出房间</SportButton></details></section>
      </div>
    </template>
    <template v-else-if="!loading && !error && home">
      <section v-if="home.requests.length" class="consumer-card"><h3>匹配中</h3><p class="consumer-muted">按同赛事、比赛类型和时间偏好匹配。找到后，会请双方确认。</p><p v-for="item in home.requests" :key="item.id">{{ item.status==='offered' ? '已有邀请，请在上方回应' : '排队中，收到邀请前可以自由取消' }} <SportButton variant="ghost" @click="stopMatch(item.id)">取消匹配</SportButton></p></section>
      <div v-if="home.rooms.length" class="gathering-grid"><router-link v-for="room in home.rooms" :key="room.id" :to="'/portal/rooms/'+room.id" class="gathering-card"><span class="room-badge">{{ room.type_name }}</span><h3>{{ room.name }}</h3><p>{{ room.event_name }} · {{ room.unit_name }}</p><div class="gathering-footer"><strong>{{ room.member_count }}/{{ room.max_members }} 人</strong><span>{{ room.registration_id ? '继续报名 →' : Number(room.member_count)===room.max_members ? '确认准备 →' : '查看房间 →' }}</span></div></router-link></div>
      <section v-if="options" class="consumer-card room-discover"><div class="between"><div><span class="room-badge">{{ options.unit.type_name }}</span><h2>{{ options.unit.unit_name || options.unit.name }}</h2><p>本场房间只收集本场名单，房主也占一个席位。</p></div></div><div class="room-create-form"><SportField v-model="name" label="房间名称" :maxlength="100" placeholder="给本场房间起个名字" :disabled="busy" /><SportButton variant="primary" :busy="busy" :disabled="!name.trim()" @click="create">创建双打房间</SportButton><SportButton variant="secondary" :busy="busy" @click="match(String(route.query.unitId))">自动匹配</SportButton></div><h3>队友招募</h3><ConsumerState v-if="!options.recruitments.length" title="暂无队友招募" description="创建房间邀请自己的搭档，或开启自动匹配。"/><article v-for="row in options.recruitments" :key="row.room_id" class="recruit-row"><SportsAvatar :nickname="row.host_nickname" :account-id="row.host_account_id" :avatar-file-id="row.avatar_file_id" :tone="row.avatar_style" compact/><div><h3>{{ row.name }}</h3><p>{{ row.message }}</p><small>{{ row.member_count }}/{{ row.max_members }} 人{{ row.team_id ? ' · 长期小队成员专属' : ' · 临时搭档也欢迎' }}</small></div><SportButton variant="primary" :disabled="busy" @click="apply(row.room_id)">申请加入</SportButton></article></section>
      <ConsumerState v-else-if="!home.rooms.length" title="暂无参赛房间" description="选择赛事的双打项目后，可以创建房间、加入招募或自动匹配。" icon="team"><router-link class="btn primary" to="/public/events">选择赛事</router-link></ConsumerState>
    </template>
    <el-dialog v-model="recruitVisible" title="发布队友招募" width="min(520px,92vw)"><p class="recruit-privacy-hint">写下参赛时间和搭档偏好。内容向本项目找队友的用户展示，请避免填写证件或私密联系方式。</p><el-input v-model="recruitMessage" type="textarea" :rows="3" maxlength="500" show-word-limit placeholder="例如：周日可参赛，期待一起认真准备的搭档"/><template #footer><SportButton variant="secondary" @click="recruitVisible=false">取消</SportButton><SportButton variant="primary" :busy="busy" :disabled="!recruitMessage.trim()" @click="recruit">发布招募</SportButton></template></el-dialog>
    </div>
  </ConsumerShell>
</template>
<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { ElMessage, ElMessageBox } from 'element-plus';
import ConsumerShell from '@/layout/consumer/ConsumerShell.vue';
import ConsumerPageHeader from '@/components/consumer/ConsumerPageHeader.vue';
import ConsumerState from '@/components/consumer/ConsumerState.vue';
import SportButton from '@/components/sport-ui/SportButton.vue';
import SportField from '@/components/sport-ui/SportField.vue';
import SportsAvatar from '@/components/consumer/SportsAvatar.vue';
import SportsProfileCard from '@/components/consumer/SportsProfileCard.vue';
import {myCertifiedHonors,type CertifiedHonor} from '@/api/sports/honorCertification';
import {publicCertifiedHonors} from '@/api/sports/certifiedDisplay';
import { getRoom, getRooms, getRoomOptions, performAction, type RoomHome, type RoomDetail, type RoomOptions, type ActionInput } from '@/api/sports/phase1';
const route=useRoute(),router=useRouter();const roomId=computed(()=>String(route.params.id||''));
const home=ref<RoomHome>(),detail=ref<RoomDetail>(),options=ref<RoomOptions>(),loading=ref(false),busy=ref(false),error=ref(''),name=ref(''),recruitVisible=ref(false),recruitMessage=ref(''),now=ref(Date.now());
const pollError=ref('');
const certifiedByAccount=ref<Record<string,CertifiedHonor[]>>({}),honorError=ref(false);
let honorGeneration=0,honorRoster='',honorFetchedAt=0;
const loadCertifiedBadges=async(force=false)=>{const room=detail.value;if(!room){++honorGeneration;certifiedByAccount.value={};honorRoster='';return;}const roster=[room.room.id,room.room.sport_id,...room.members.map(member=>member.account_id)].join(':');if(!force&&roster===honorRoster&&Date.now()-honorFetchedAt<60000)return;const stamp=++honorGeneration;if(roster!==honorRoster)certifiedByAccount.value={};honorRoster=roster;honorFetchedAt=Date.now();const results=await Promise.allSettled(room.members.map(async member=>({accountId:member.account_id,honors:(await(member.account_id===room.accountId?myCertifiedHonors(room.room.sport_id):publicCertifiedHonors(member.account_id,room.room.sport_id))).data})));if(stamp!==honorGeneration)return;const records:Record<string,CertifiedHonor[]>={};for(const result of results)if(result.status==='fulfilled')records[result.value.accountId]=result.value.honors;certifiedByAccount.value=records;honorError.value=results.some(result=>result.status==='rejected');};
const visibleOffers=computed(()=>home.value?.offers.filter(o=>!roomId.value||o.room_id===roomId.value||o.unit_id===detail.value?.room.unit_id)||[]);
const visibleRequests=computed(()=>home.value?.requests.filter(r=>!roomId.value||r.room_id===roomId.value)||[]);
const myMember=computed(()=>detail.value?.members.find(m=>m.account_id===detail.value?.accountId));const isHost=computed(()=>detail.value?.room.host_account_id===detail.value?.accountId);const allReady=computed(()=>!!detail.value&&detail.value.members.length===detail.value.room.max_members&&detail.value.members.every(m=>m.ready));
const cheers=['队友加油','记得带球拍','提前十分钟热身'];
const remaining=(date:string)=>Math.max(0,Math.ceil((new Date(date).getTime()-now.value)/1000));
let loadRevision=0;
const load=async(silent=false)=>{const revision=++loadRevision,id=roomId.value;if(!silent){loading.value=true;error.value='';}try{if(id){const [room,list]=await Promise.all([getRoom(id),getRooms()]);if(revision!==loadRevision)return;detail.value=room.data;home.value=list.data;options.value=undefined;}else{const list=await getRooms();if(revision!==loadRevision)return;detail.value=undefined;home.value=list.data;if(route.query.unitId){const result=await getRoomOptions(String(route.query.unitId));if(revision!==loadRevision)return;options.value=result.data;}else options.value=undefined;}await loadCertifiedBadges(!silent);pollError.value='';}catch(e){if(revision!==loadRevision)return;const message=e instanceof Error?e.message:'暂时无法读取，请稍后重试';if(silent)pollError.value='状态同步暂时中断，请重新同步后继续操作。';else error.value=message;}finally{if(revision===loadRevision&&!silent)loading.value=false;}};
const run=async(code:string,input:ActionInput,message?:string)=>{if(busy.value)return;if(pollError.value){ElMessage.warning('请先重新同步房间状态，再继续操作');return;}busy.value=true;try{const res=await performAction(code,input,message);await load(true);return res.data;}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'暂时未能完成，请核对当前状态');}finally{busy.value=false;}};
const roomInput=()=>({roomId:roomId.value,expectedVersion:detail.value?.room.version||0});
const ready=()=>run('room.ready',{...roomInput(),ready:!myMember.value?.ready});
const encourage=(message:string)=>run('room.encourage',{roomId:roomId.value,message});
const create=async()=>{const receipt=await run('room.create',{unitId:String(route.query.unitId),name:name.value,...(route.query.teamId?{teamId:String(route.query.teamId)}:{})});if(receipt)await router.push('/portal/rooms/'+receipt.result.roomId);};
const match=(unitId:string,room?:string)=>run('room.match',{unitId,...(room?{roomId:room}:{}),timePreference:'any'});
const stopMatch=(requestId:string)=>run('room.stopMatch',{requestId});
const answer=async(offerId:string,answer:string)=>{const receipt=await run('room.answer',{offerId,answer},answer==='accept'?'接受这次组队邀请。所有成员同意后才进入房间；正式报名仍需本人确认资料和声明。':'拒绝这次邀请，匹配席位将释放。');if(receipt?.result.roomId)await router.push('/portal/rooms/'+receipt.result.roomId);};
const apply=(roomId:string)=>run('room.apply',{roomId});
const recruit=async()=>{const receipt=await run('room.recruit',{...roomInput(),message:recruitMessage.value},'发布本场缺员招募，队长昵称和招募介绍将向寻找该项目搭档的人展示。');if(receipt)recruitVisible.value=false;};
const prepare=async()=>{const receipt=await run('room.prepare',roomInput(),'为当前成员生成报名草稿，各人需继续确认参赛资料和声明。');if(receipt)await router.push('/portal/registration/detail/'+receipt.result.registrationId);};
const editAnnouncement=async()=>{try{const res=await ElMessageBox.prompt('告诉队友本场需要注意的事','房间公告',{inputValue:detail.value?.room.announcement||'',inputValidator:value=>!!value&&value.length<=500||'请填写500字内的公告'});await run('room.announce',{...roomInput(),message:res.value});}catch{ /* cancelled */ }};
const leave=async()=>{let newHostAccountId:string|undefined;const others=detail.value?.members.filter(m=>m.account_id!==detail.value?.accountId)||[];if(isHost.value&&others.length)newHostAccountId=others[0].account_id;const receipt=await run('room.leave',{...roomInput(),...(newHostAccountId?{newHostAccountId}:{})},newHostAccountId?'退出后将由 '+others[0].nickname+' 接任房主。本场还未生成正式报名。':'退出这个尚未报名的房间？');if(receipt)await router.push('/portal/rooms');};
let clock:ReturnType<typeof setInterval>;let poll:ReturnType<typeof setInterval>;
onMounted(()=>{load();clock=setInterval(()=>{now.value=Date.now();},1000);poll=setInterval(()=>{if(!busy.value&&!loading.value&&!recruitVisible.value)load(true);},10000);});onUnmounted(()=>{++honorGeneration;clearInterval(clock);clearInterval(poll);});watch(()=>route.fullPath,()=>load());
</script>
<style scoped>
