.premium-rooms{position:relative}.premium-rooms .room-stage{background:var(--s-surface,#fff);border:0;border-radius:25px;padding:32px 35px;margin:25px 0;box-shadow:none}.room-context{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;margin-bottom:16px}.room-context h2{font-size:24px;letter-spacing:-.04em;margin:0 0 9px;font-weight:600;line-height:1.4}.room-context a,.room-context span:not(.room-badge){font-size:12px;color:var(--s-muted);line-height:1.8}.room-topline{display:flex;justify-content:space-between;gap:14px;font-size:11px;color:var(--s-muted);padding:14px 0;border-bottom:1px solid var(--s-line)}.room-badge{display:inline-flex;background:#ecefe7;color:#7c8a70;border-radius:20px;padding:6px 10px;font-size:10px;font-weight:500;flex-shrink:0}.team-banner{display:flex;align-items:center;justify-content:center;gap:10px;padding:13px;border-radius:12px;background:#f5f0e3;color:#9a8053;margin:20px 0;font-size:12px}.premium-rooms .room-seats{display:flex;align-items:flex-start;justify-content:center;gap:80px;padding:34px 0 18px;margin:15px 0;position:relative}.room-seats:before{content:'';position:absolute;height:1px;width:180px;top:118px;background:linear-gradient(90deg,transparent,var(--s-line),transparent)}.room-seats>*{position:relative;z-index:1}.empty-seat{display:flex;align-items:center;flex-direction:column;min-width:110px;gap:11px;color:var(--s-muted);padding-top:30px}.empty-seat>button,.empty-seat>span{display:grid;place-items:center;height:100px;width:100px;border:1px dashed #cad1c4;border-radius:50%;background:var(--s-paper,#f5f5f3);color:#aab4a1;font-size:30px;margin-bottom:10px;line-height:1;transition:background .25s,transform .25s}.empty-seat>button{cursor:pointer}.empty-seat>button:hover{background:#f1e6dc;color:var(--s-primary);transform:scale(1.035)}.empty-seat strong{font-size:14px;font-weight:500;color:#8d9785}.empty-seat small{font-size:11px}.room-actions{display:flex;justify-content:center;gap:9px;flex-wrap:wrap;margin